import type { Recipe, RecipeIngredient, RecipeStep } from '../mocks';
import type { SampleFoodImageKey } from './sampleFoodImages';

// Okyo recommendation recipes (seed data).
//
// These are non-scan "food inspiration" recipes shown on Home and Discover so the
// app feels alive before a user scans anything. They are real, specific, cookable
// recipes that follow Okyo's quality rules: exact amounts, named ingredients,
// numbered steps with timing + visual cues, substitutions, and honest cost.
//
// Honesty: estimatedSavings is 0 (there is no scanned restaurant price), and
// estimatedHomemadeCost is a clearly-labeled home-kitchen estimate. Recipe Detail
// only shows savings when restaurantPrice > 0 AND savings > 0, so these correctly
// show "Homemade estimate" instead of any fake savings.
//
// This is a small starter set (15 recipes). A larger 100-item pack can be added
// later by appending specs here or loading a generated manifest — the card UI and
// category browsing already scale to any length.

export type MealTime = 'morning' | 'afternoon' | 'evening' | 'late_night';

export type RecommendationCategory =
  | 'Breakfast & Brunch'
  | 'Proteins & Mains'
  | 'Pasta & Noodles'
  | 'Bowls & Grains'
  | 'Salads & Vegetables'
  | 'Handheld & Wraps'
  | 'Soups & Stews'
  | 'Vegetarian'
  | 'Desserts & Treats'
  | 'Dinner & Cooking Methods';

// Every category shown in the Discover recipe library. Order here is the
// browse order users see, grouped loosely by meal type -> cuisine -> diet/method.
export const recommendationCategories: RecommendationCategory[] = [
  'Breakfast & Brunch',
  'Proteins & Mains',
  'Pasta & Noodles',
  'Bowls & Grains',
  'Salads & Vegetables',
  'Handheld & Wraps',
  'Soups & Stews',
  'Vegetarian',
  'Desserts & Treats',
  'Dinner & Cooking Methods',
];

const categoryArt: Record<RecommendationCategory, { tint: string }> = {
  'Breakfast & Brunch': { tint: '#fce5c8' },
  'Proteins & Mains': { tint: '#edbdac' },
  'Pasta & Noodles': { tint: '#f8d29a' },
  'Bowls & Grains': { tint: '#e8dfa6' },
  'Salads & Vegetables': { tint: '#c4e3ba' },
  'Handheld & Wraps': { tint: '#ecc9a7' },
  'Soups & Stews': { tint: '#ecd3b3' },
  'Vegetarian': { tint: '#c7e5bb' },
  'Desserts & Treats': { tint: '#edcccf' },
  'Dinner & Cooking Methods': { tint: '#fff7cc' },
};

export function getCategoryArt(category: RecommendationCategory) {
  return categoryArt[category];
}

export type RecommendationRecipe = Recipe & {
  category: RecommendationCategory;
  mealTimes: MealTime[];
  blurb: string;
  tint: string;
  // Extra browse buckets this recipe should also show up under, in addition to
  // its one primary `category`. E.g. "Kimchi Fried Rice" has category
  // 'Grains & Rice Bowls' but also carries the 'Noodles & Asian' and 'Simple'
  // tags, so it's findable from either the Asian tile or the Simple tile.
  tags: RecommendationCategory[];
};

type RecommendationSpec = {
  id: string;
  title: string;
  category: RecommendationCategory;
  mealTimes: MealTime[];
  difficulty: Recipe['difficulty'];
  prep: number;
  cook: number;
  servings: number;
  homemadeCost: number;
  blurb: string;
  ingredients: Array<[quantity: string, name: string]>;
  steps: Array<{ text: string; time?: string; cue?: string }>;
  substitutions: string[];
  equipment: string[];
  imageKey?: SampleFoodImageKey;
  // Pexels photo ID for a per-recipe image. License: Pexels License (free commercial use, no attribution required).
  // URL resolved at build time: https://images.pexels.com/photos/{id}/pexels-photo-{id}.jpeg?auto=compress&cs=tinysrgb&w=600
  pexelsId?: number;
  pantryNote: string;
  // Draft recipes are dish names reserved for the library but not yet authored:
  // their ingredients and steps are placeholder scaffolding, not a real recipe.
  // They are excluded from every exported list so they can never reach the UI.
  // Clear this flag only once a recipe has real ingredients and real steps.
  draft?: boolean;
};

// Keyword -> extra browse category, checked against the title + ingredient
// names. This lets a dish surface under multiple tiles.
const CUISINE_TAG_KEYWORDS: Array<[RecommendationCategory, string[]]> = [
  ['Pasta & Noodles', ['fried rice', 'teriyaki', 'stir-fry', 'stir fry', 'bibimbap', 'pad thai', 'pad see ew',
    'pad kee mao', 'sushi', 'kimchi', 'ramen', 'udon', 'soba', 'dumpling', 'spring roll', 'egg roll',
    'katsu', 'bulgogi', 'char siu', 'al pastor', 'general tso', 'orange chicken', 'sesame chicken',
    'congee', 'chow fun', 'chow mein', 'char kway teow', 'vermicelli', 'japchae', 'miso', 'wonton', 'noodle']],
  ['Handheld & Wraps', ['taco', 'burrito', 'quesadilla', 'enchilada', 'fajita', 'salsa', 'guacamole', 'elote',
    'empanada', 'arepa', 'ceviche', 'carnitas', 'barbacoa', 'pozole', 'mole poblano', 'tamale', 'nacho',
    'chorizo', 'ropa vieja', 'huarache', 'sope', 'lomo saltado']],
  ['Vegetarian', ['shawarma', 'falafel', 'hummus', 'tzatziki', 'gyro', 'souvlaki', 'tabbouleh', 'tagine',
    'kofta', 'halloumi', 'baklava', 'pita', "za'atar", 'grape leaves', 'fattoush', 'baba ganoush',
    'curry', 'masala', 'tikka', 'tandoori', 'paneer', 'naan', 'dal ', 'biryani', 'vindaloo',
    'korma', 'rogan josh', 'saag', 'chana', 'aloo gobi', 'samosa', 'baingan bharta', 'vegan', 'vegetarian']],
  ['Proteins & Mains', ['shrimp', 'salmon', 'cod fillet', 'tilapia', 'scallop', 'crab', 'lobster', 'mussel', 'clam',
    'tuna steak', 'swordfish', 'trout', 'octopus', 'steak', 'beef', 'chicken', 'pork', 'fish']],
];

// Any meat, poultry, seafood, or fish-derived ingredient. Used to decide the
// 'Vegetarian' tag from real ingredients instead of trusting a hand-typed
// category. Deliberately broad: a false negative here would put meat in front
// of someone browsing plant-based food, which is the worse failure.
const ANIMAL_PROTEIN =
  /\b(chicken|beef|pork|lamb|veal|duck|turkey|bacon|sausage|steak|brisket|ham|prosciutto|pancetta|chorizo|pepperoni|salami|meatball|ground (?:meat|beef|pork|turkey|lamb)|oxtail|gelatin|lard|anchov|fish|salmon|tuna|cod|tilapia|halibut|trout|bass|snapper|sardine|shrimp|prawn|crab|lobster|scallop|clam|mussel|oyster|squid|calamari|octopus|shellfish|seafood)\b/;

// Dish names that are soups or stews regardless of their primary category.
const SOUP_LIKE = /\b(soup|stew|chowder|bisque|broth|ramen|pho|chili|gumbo|minestrone)\b/i;

function computeTags(spec: RecommendationSpec): RecommendationCategory[] {
  const tags = new Set<RecommendationCategory>();
  const searchText = [spec.title, ...spec.ingredients.map(([, name]) => name)].join(' ').toLowerCase();

  for (const [tagCategory, keywords] of CUISINE_TAG_KEYWORDS) {
    if (tagCategory === spec.category) {
      continue;
    }
    if (keywords.some((kw) => searchText.includes(kw))) {
      tags.add(tagCategory);
    }
  }

  // 'Vegetarian' is a DIET, not a cuisine, so it is derived from the actual
  // ingredients rather than hand-assigned. Deriving it is what guarantees a
  // lamb tagine can never appear under Vegetarian again.
  const containsAnimalProtein = ANIMAL_PROTEIN.test(searchText);
  if (containsAnimalProtein) {
    tags.delete('Vegetarian');
  } else {
    tags.add('Vegetarian');
  }

  // Soups are recognisable from the dish name and often live in another
  // primary category (ramen and pho are served in bowls, for instance).
  if (SOUP_LIKE.test(spec.title)) {
    tags.add('Soups & Stews');
  }

  tags.delete(spec.category);
  return Array.from(tags);
}

function buildRecommendation(spec: RecommendationSpec): RecommendationRecipe {
  const ingredients: RecipeIngredient[] = spec.ingredients.map(([quantity, name]) => ({ name, quantity }));
  const structuredSteps: RecipeStep[] = spec.steps.map((step) => ({
    text: step.text,
    timeEstimate: step.time,
    visualCue: step.cue,
  }));
  const art = categoryArt[spec.category];

  return {
    id: `rec-${spec.id}`,
    scanResultId: `rec-${spec.id}`,
    imageStatus: 'ready',
    // Built-in art is resolved from assets/food at render time via the stable
    // `rec-` ID. Do not persist a cache URI or require a CDN for library art.
    imageUrl: undefined,
    title: spec.title,
    mode: 'Normal',
    description: spec.blurb,
    prepTimeMinutes: spec.prep,
    cookTimeMinutes: spec.cook,
    totalTimeMinutes: spec.prep + spec.cook,
    servings: spec.servings,
    difficulty: spec.difficulty,
    skillLevel: spec.difficulty,
    estimatedHomemadeCost: spec.homemadeCost,
    estimatedSavings: 0,
    ingredients,
    steps: structuredSteps.map((step) => step.text),
    structuredSteps,
    substitutions: spec.substitutions,
    pantryNote: spec.pantryNote,
    confidenceNote: 'Okyo recommended recipe. Cost is a home-kitchen estimate.',
    equipment: spec.equipment,
    category: spec.category,
    mealTimes: spec.mealTimes,
    blurb: spec.blurb,
    tint: art.tint,
    tags: computeTags(spec),
  };
}

