// Only authored recipes are published. Draft entries stay in this file as the
// roadmap for the library, but are filtered out here so nothing half-written
// can surface in the app.
const publishedSpecs = specs.filter((spec) => !spec.draft);

export const recommendedRecipes: RecommendationRecipe[] = publishedSpecs.map(buildRecommendation);

/** Dish names reserved but not yet authored. Useful for planning batches. */
export const draftRecipeCount = specs.length - publishedSpecs.length;

export function getRecommendationsByCategory(category: RecommendationCategory): RecommendationRecipe[] {
  return recommendedRecipes.filter((recipe) => recipe.category === category || recipe.tags.includes(category));
}

export function getRecommendationsForMealTime(mealTime: MealTime, limit = 6): RecommendationRecipe[] {
  const matches = recommendedRecipes.filter((recipe) => recipe.mealTimes.includes(mealTime));
  // Fall back to the full set if a meal time has too few tagged recipes.
  const source = matches.length >= 4 ? matches : recommendedRecipes;
  return source.slice(0, limit);
}

export function getMealTimeForHour(hour: number): MealTime {
  if (hour >= 22 || hour < 5) {
    return 'late_night';
  }
  if (hour < 11) {
    return 'morning';
  }
  if (hour < 17) {
    return 'afternoon';
  }
  return 'evening';
}

export function getRecommendationById(id: string): RecommendationRecipe | undefined {
  return recommendedRecipes.find((recipe) => recipe.id === id);
}
